const input = $input.first();
const records = (input && input.json && input.json.records) || [];
return records
  .map((rec) => {
    const f = rec.fields || {};
    return {
      json: {
        supplier: f.Supplier,
        region: f.Region,
        query: f['Search Query'],
        riskThreshold: (typeof f['Risk Threshold'] === 'number') ? f['Risk Threshold'] : 70
      },
      pairedItem: 0
    };
  })
  .filter((item) => item.json.supplier && item.json.query);

const results = [];
$input.all().forEach((item, i) => {
  const watch = $('Normalize Watchlist').all()[i] ? $('Normalize Watchlist').all()[i].json : {};
  const articles = (item.json && item.json.articles) || [];
  articles.forEach((article) => {
    results.push({
      json: {
        supplier: watch.supplier,
        region: watch.region,
        riskThreshold: watch.riskThreshold,
        title: article.title,
        description: article.description || '',
        url: article.url,
        source: (article.source && article.source.name) || '',
        publishedAt: article.publishedAt
      },
      pairedItem: i
    });
  });
});
return results;

const article = $('Extract Articles').item.json;
const systemPrompt = 'You are a supply chain risk analyst. Read the news article about a supplier or its region and assess disruption risk. Respond with ONLY a JSON object: {"risk_score": <integer 0-100>, "risk_category": <"Low"|"Medium"|"High"|"Critical">, "reasoning": <one sentence>}. Score based on how likely the article describes an active or imminent supply chain disruption (strikes, natural disasters, factory closures, shipping or port issues, trade restrictions, geopolitical instability) versus routine or unrelated news.';
const userPrompt = 'Supplier: ' + article.supplier + '\nRegion: ' + article.region + '\nArticle title: ' + article.title + '\nArticle description: ' + article.description;
return {
  json: Object.assign({}, article, {
    groqRequestBody: {
      model: 'openai/gpt-oss-120b',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  })
};

const article = $('Build Risk Prompt').item.json;
let parsed = {};
try {
  const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {};
}
const riskScoreNum = Number(parsed.risk_score);
const riskScore = Number.isFinite(riskScoreNum) ? riskScoreNum : 0;
const riskCategory = parsed.risk_category || 'Low';
const reasoning = parsed.reasoning || 'No reasoning returned by the model.';
const riskThreshold = (typeof article.riskThreshold === 'number') ? article.riskThreshold : 70;
const shouldAlert = riskCategory === 'High' || riskCategory === 'Critical' || riskScore >= riskThreshold;
const slackText = ':rotating_light: Supply chain risk alert (' + riskCategory + ', score ' + riskScore + ')\n' +
  'Supplier: ' + article.supplier + '  Region: ' + article.region + '\n' +
  'Article: ' + article.title + '\n' + article.url + '\n' +
  'Why: ' + reasoning;
const emailSubject = '[Supply Chain Alert] ' + riskCategory + ' risk - ' + article.supplier + ' (' + article.region + ')';
const emailBody = 'A ' + riskCategory + ' risk signal (score ' + riskScore + '/100, threshold ' + riskThreshold + ') was detected for ' + article.supplier + ' in ' + article.region + '.\n\n' +
  'Article: ' + article.title + '\n' +
  'Link: ' + article.url + '\n' +
  'Source: ' + article.source + '\n' +
  'Published: ' + article.publishedAt + '\n\n' +
  'Why this was flagged: ' + reasoning + '\n\n' +
  '-- Supply Chain Disruption Alert System';
return {
  json: {
    supplier: article.supplier,
    region: article.region,
    title: article.title,
    url: article.url,
    source: article.source,
    publishedAt: article.publishedAt,
    riskScore: riskScore,
    riskCategory: riskCategory,
    reasoning: reasoning,
    riskThreshold: riskThreshold,
    shouldAlert: shouldAlert,
    slackText: slackText,
    emailSubject: emailSubject,
    emailBody: emailBody
  }
};
